-- Tables and views of the dbt test project in datafold/data-diff
-- (tests/dbt_artifacts/jaffle_shop.duckdb), schemas prod and dev only, regenerated as
-- SQL. Run it in a DuckDB database file named jaffle_shop.duckdb: the views refer to
-- the catalog by that name. See NOTICE.md.

CREATE SCHEMA prod;
CREATE SCHEMA dev;
CREATE TABLE prod.customers (customer_id INTEGER, first_name VARCHAR, last_name VARCHAR, first_order DATE, most_recent_order DATE, number_of_orders BIGINT, customer_lifetime_value DOUBLE);
CREATE TABLE prod.orders (order_id INTEGER, customer_id INTEGER, order_date DATE, status VARCHAR, credit_card_amount DOUBLE, coupon_amount DOUBLE, bank_transfer_amount DOUBLE, gift_card_amount DOUBLE, amount DOUBLE);
CREATE TABLE prod.raw_customers (id INTEGER, first_name VARCHAR, last_name VARCHAR);
CREATE TABLE prod.raw_orders (id INTEGER, user_id INTEGER, order_date DATE, status VARCHAR);
CREATE TABLE prod.raw_payments (id INTEGER, order_id INTEGER, payment_method VARCHAR, amount INTEGER);
CREATE TABLE dev.customers (customer_id INTEGER, first_name VARCHAR, last_name VARCHAR, first_order DATE, most_recent_order DATE, number_of_orders BIGINT, customer_lifetime_value DOUBLE);
CREATE TABLE dev.orders (order_id INTEGER, customer_id INTEGER, order_date VARCHAR, new_column INTEGER, credit_card_amount DOUBLE, coupon_amount DOUBLE, bank_transfer_amount DOUBLE, gift_card_amount DOUBLE, amount DOUBLE);
CREATE TABLE dev.raw_customers (id INTEGER, first_name VARCHAR, last_name VARCHAR);
CREATE TABLE dev.raw_orders (id INTEGER, user_id INTEGER, order_date DATE, status VARCHAR);
CREATE TABLE dev.raw_payments (id INTEGER, order_id INTEGER, payment_method VARCHAR, amount INTEGER);
CREATE VIEW prod.stg_customers (customer_id, first_name, last_name) AS WITH "source" AS (SELECT * FROM jaffle_shop.prod.raw_customers), renamed AS (SELECT id AS customer_id, first_name, last_name FROM "source") SELECT * FROM renamed;
CREATE VIEW prod.stg_orders (order_id, customer_id, order_date, status) AS WITH "source" AS (SELECT * FROM jaffle_shop.prod.raw_orders), renamed AS (SELECT id AS order_id, user_id AS customer_id, order_date, status FROM "source") SELECT * FROM renamed;
CREATE VIEW prod.stg_payments (payment_id, order_id, payment_method, amount) AS WITH "source" AS (SELECT * FROM jaffle_shop.prod.raw_payments), renamed AS (SELECT id AS payment_id, order_id, payment_method, (amount / 100) AS amount FROM "source") SELECT * FROM renamed;
CREATE VIEW dev.stg_customers (customer_id, first_name, last_name) AS WITH "source" AS (SELECT * FROM jaffle_shop.dev.raw_customers), renamed AS (SELECT id AS customer_id, first_name, last_name FROM "source") SELECT * FROM renamed;
CREATE VIEW dev.stg_orders (order_id, customer_id, order_date, status) AS WITH "source" AS (SELECT * FROM jaffle_shop.dev.raw_orders), renamed AS (SELECT id AS order_id, user_id AS customer_id, order_date, status FROM "source") SELECT * FROM renamed;
CREATE VIEW dev.stg_payments (payment_id, order_id, payment_method, amount) AS WITH "source" AS (SELECT * FROM jaffle_shop.dev.raw_payments), renamed AS (SELECT id AS payment_id, order_id, payment_method, (amount / 100) AS amount FROM "source") SELECT * FROM renamed;
